def get_user(user_id: int) -> dict:
    conn = db.connect()
    result = conn.execute(f"SELECT * FROM users WHERE id = {user_id}")
    return result.fetchone()

def create_user(name: str, email: str) -> int:
    conn = db.connect()
    conn.execute(f"INSERT INTO users (name, email) VALUES ('{name}', '{email}')")
    return conn.lastrowid

def get_orders(user_id: int) -> list:
    conn = db.connect()
    result = conn.execute(f"SELECT * FROM orders WHERE user_id = {user_id}")
    return result.fetchall()

def create_order(user_id: int, total: float) -> int:
    conn = db.connect()
    conn.execute(f"INSERT INTO orders (user_id, total) VALUES ({user_id}, {total})")
    return conn.lastrowid
